-- =============================================================================
-- OPTIONAL DEMO DATA (about 100 records of each kind)
-- The project brief asks for test data that is big enough to look like a real
-- system. This file adds it. It has the same recipe as server/scripts/seed.js,
-- but it only INSERTS: it never deletes or changes rows that already exist.
--
-- HOW TO RUN: open the Supabase SQL Editor, paste this whole file and click Run.
-- Run the numbered files 01 to 06 first, so the tables exist.
-- Run it once. A second run adds nothing, because every insert skips rows that
-- are already there (same user ID, category name, company owner, project name
-- for the same designer, and shortlist pair).
--
-- WHAT IT ADDS
--   4 user profiles (only if they are missing)
--   210 accounts: 101 Interior Designers, 101 Customers, 4 staff, 4 demo logins
--   100 IDP categories, 101 companies (one for each designer)
--   100 IDPs (about 6 in 10 current, the rest past) with view counts
--   100 shortlist items
-- Rows get created dates over the last 38 days, so the daily, weekly and monthly
-- reports show different numbers.
--
-- LOGINS: admin1, designer1, customer1, manager1. Every account uses the same
-- test password as scripts/seed.js (set DEMO_PASSWORD there).
-- About 1 in 10 of the generated Customers is suspended, to show story #9.
-- Generated with a fixed random seed, so the data is the same every time.
-- =============================================================================

BEGIN;

-- 1. The four roles (only the ones that are missing)
INSERT INTO public.user_profile (name, description, "createdAt", "updatedAt")
SELECT v.name, v.description, NOW(), NOW()
FROM (VALUES
    ('User Admin', 'Manages user accounts and profiles'),
    ('Interior Designer', 'Manages company info and IDP portfolio'),
    ('Customer', 'Searches, views and shortlists IDPs'),
    ('Platform Manager', 'Manages IDP categories and reports')
) AS v(name, description)
WHERE NOT EXISTS (SELECT 1 FROM public.user_profile p WHERE p.name = v.name);

-- 2. Accounts (210)
