JOIN public.user_account cu ON cu.username = v.customer
JOIN public.user_account de ON de.username = v.designer
JOIN public.interior_design_project p ON p.designer_account_id = de.id AND p.name = v.project
WHERE NOT EXISTS (
  SELECT 1 FROM public.shortlist_item s WHERE s.customer_account_id = cu.id AND s.project_id = p.id
);

COMMIT;

-- Check: how many rows each table has now.
SELECT 'user_profile' AS table_name, COUNT(*) AS total FROM public.user_profile
UNION ALL SELECT 'user_account', COUNT(*) FROM public.user_account
UNION ALL SELECT 'idp_category', COUNT(*) FROM public.idp_category
UNION ALL SELECT 'company', COUNT(*) FROM public.company
UNION ALL SELECT 'interior_design_project', COUNT(*) FROM public.interior_design_project
UNION ALL SELECT 'shortlist_item', COUNT(*) FROM public.shortlist_item;
